def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))

    tests = [fmt([5]), fmt([3, 3, 3]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]), fmt([-10 ** 9, 10 ** 9, -10 ** 9, 10 ** 9]),
             fmt([0, 0, 1, 0, 0, 1, 0]), fmt([70, 71, 69, 72, 68, 73])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(3):
            hi = rng.choice([2, 5, 20, 1000])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10 ** 9, 10 ** 9) for _ in range(N)]))
    tests.append(fmt(list(range(-N // 2, N // 2))))
    tests.append(fmt(list(range(N, 0, -1))))
    tests.append(fmt([rng.randint(0, 3) for _ in range(N)]))
    tests.append(fmt([(i % 1000) * 1000 - 500000 for i in range(N)]))
    return tests
